import{_ as i,a0 as l,w as p,s as a,I as t,x as o,a1 as n,A as s,ao as u}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const C=JSON.parse('{"title":"在 Linux 中使用日誌來排錯 | LCTT x X-CMD","titleTemplate":false,"description":"在 Linux 中使用日誌來排錯 | LCTT (201508) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Linux 中使用日誌來排錯 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Linux 中使用日誌來排錯 | LCTT (201508) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201508/20150803 Troubleshooting with Linux Logs","title":"在 Linux 中使用日誌來排錯","tag":"201508","desc":""},"relativePath":"201508/20150803 Troubleshooting with Linux Logs.md","filePath":"[post].md"}'),d={name:"201508/20150803 Troubleshooting with Linux Logs.md"};function g(m,e,h,f,x,b){const r=l("Link");return p(),a("div",null,[e[20]||(e[20]=t("h1",{id:"在-linux-中使用日誌來排錯",tabindex:"-1"},[o("在 Linux 中使用日誌來排錯 "),t("a",{class:"header-anchor",href:"#在-linux-中使用日誌來排錯","aria-label":"Permalink to “在 Linux 中使用日誌來排錯”"},"​")],-1)),e[21]||(e[21]=t("p",null,"人們創建日誌的主要原因是排錯。通常你會診斷為什麼問題發生在你的 Linux 系統或應用程序中。錯誤信息或一系列的事件可以給你提供找出根本原因的線索，説明問題是如何發生的，並指出如何解決它。這裏有幾個使用日誌來解決的樣例。",-1)),e[22]||(e[22]=t("h3",{id:"登錄失敗原因",tabindex:"-1"},[o("登錄失敗原因 "),t("a",{class:"header-anchor",href:"#登錄失敗原因","aria-label":"Permalink to “登錄失敗原因”"},"​")],-1)),t("p",null,[e[1]||(e[1]=o("如果你想檢查你的系統是否安全，你可以在驗證日誌中檢查登錄失敗的和登錄成功但可疑的用户。當有人通過不正當或無效的憑據來登錄時會出現認證失敗，這通常發生在使用 SSH 進行遠程登錄或 su 到本地其他用户來進行訪問權時。這些是由",-1)),n(r,{href:"http://linux.die.net/man/8/pam.d"},{default:s(()=>[...e[0]||(e[0]=[o("插入式驗證模組（PAM）",-1)])]),_:1}),e[2]||(e[2]=o("來記錄的。在你的日誌中會看到像 Failed password 和 user unknown 這樣的字符串。而成功認證記錄則會包括像 Accepted password 和 session opened 這樣的字符串。",-1))]),e[23]||(e[23]=u(`<p>失敗的例子:</p><pre><code>pam_unix(sshd:auth): authentication failure; logname= uid=0 euid=0 tty=ssh ruser= rhost=10.0.2.2
Failed password for invalid user hoover from 10.0.2.2 port 4791 ssh2
pam_unix(sshd:auth): check pass; user unknown
PAM service(sshd) ignoring max retries; 6 &gt; 3
</code></pre><p>成功的例子：</p><pre><code>Accepted password for hoover from 10.0.2.2 port 4792 ssh2
pam_unix(sshd:session): session opened for user hoover by (uid=0)
pam_unix(sshd:session): session closed for user hoover
</code></pre><p>你可以使用 grep 來查找哪些用户失敗登錄的次數最多。這些都是潛在的攻擊者正在嘗試和訪問失敗的賬户。這是一個在 ubuntu 系統上的例子。</p><pre><code>$ grep &quot;invalid user&quot; /var/log/auth.log | cut -d &#39; &#39; -f 10 | sort | uniq -c | sort -nr
23 oracle
18 postgres
17 nagios
10 zabbix
6 test
</code></pre><p>由於沒有標準格式，所以你需要為每個應用程序的日誌使用不同的命令。日誌管理系統，可以自動分析日誌，將它們有效的歸類，幫助你提取關鍵字，如用户名。</p><p>日誌管理系統可以使用自動解析功能從 Linux 日誌中提取用户名。這使你可以看到用户的信息，並能通過點擊過濾。在下面這個例子中，我們可以看到，root 用户登錄了 2700 次之多，因為我們篩選的日誌僅顯示 root 用户的嘗試登錄記錄。</p><p><img src="http://www.loggly.com/ultimate-guide/wp-content/uploads/2015/05/Screen-Shot-2015-03-12-at-11.05.36-AM.png" alt=""></p><p>日誌管理系統也可以讓你以時間為做座標軸的圖表來查看，使你更容易發現異常。如果有人在幾分鐘內登錄失敗一次或兩次，它可能是一個真正的用户而忘記了密碼。但是，如果有幾百個失敗的登錄並且使用的都是不同的用户名，它更可能是在試圖攻擊系統。在這裏，你可以看到在3月12日，有人試圖登錄 Nagios 幾百次。這顯然​​不是一個合法的系統用户。</p><p><img src="http://www.loggly.com/ultimate-guide/wp-content/uploads/2015/05/Screen-Shot-2015-03-12-at-11.12.18-AM.png" alt=""></p><h3 id="重啓的原因" tabindex="-1">重啓的原因 <a class="header-anchor" href="#重啓的原因" aria-label="Permalink to “重啓的原因”">​</a></h3><p>有時候，一台服務器由於系統崩潰或重啓而宕機。你怎麼知道它何時發生，是誰做的？</p><h4 id="關機命令" tabindex="-1">關機命令 <a class="header-anchor" href="#關機命令" aria-label="Permalink to “關機命令”">​</a></h4><p>如果有人手動運行 shutdown 命令，你可以在驗證日誌文件中看到它。在這裏，你可以看到，有人從 IP 50.0.134.125 上作為 ubuntu 的用户遠程登錄了，然後關閉了系統。</p><pre><code>Mar 19 18:36:41 ip-172-31-11-231 sshd[23437]: Accepted publickey for ubuntu from 50.0.134.125 port 52538 ssh
Mar 19 18:36:41 ip-172-31-11-231 23437]:sshd[ pam_unix(sshd:session): session opened for user ubuntu by (uid=0)
Mar 19 18:37:09 ip-172-31-11-231 sudo:   ubuntu : TTY=pts/1 ; PWD=/home/ubuntu ; USER=root ; COMMAND=/sbin/shutdown -r now
</code></pre><h4 id="內核初始化" tabindex="-1">內核初始化 <a class="header-anchor" href="#內核初始化" aria-label="Permalink to “內核初始化”">​</a></h4><p>如果你想看看服務器重新啓動的所有原因（包括崩潰），你可以從內核初始化日誌中尋找。你需要搜索內核類（kernel）和 cpu 初始化（Initializing）的信息。</p><pre><code>Mar 19 18:39:30 ip-172-31-11-231 kernel: [    0.000000] Initializing cgroup subsys cpuset
Mar 19 18:39:30 ip-172-31-11-231 kernel: [    0.000000] Initializing cgroup subsys cpu
Mar 19 18:39:30 ip-172-31-11-231 kernel: [    0.000000] Linux version 3.8.0-44-generic (buildd@tipua) (gcc version 4.6.3 (Ubuntu/Linaro 4.6.3-1ubuntu5) ) #66~precise1-Ubuntu SMP Tue Jul 15 04:01:04 UTC 2014 (Ubuntu 3.8.0-44.66~precise1-generic 3.8.13.25)
</code></pre><h3 id="檢測內存問題" tabindex="-1">檢測內存問題 <a class="header-anchor" href="#檢測內存問題" aria-label="Permalink to “檢測內存問題”">​</a></h3><p>有很多原因可能導致服務器崩潰，但一個常見的原因是內存用盡。</p><p>當你係統的內存不足時，進程會被殺死，通常會殺死使用最多資源的進程。當系統使用了所有內存，而新的或現有的進程試圖使用更多的內存時就會出現錯誤。在你的日誌文件查找像 Out of Memory 這樣的字符串或類似 kill 這樣的內核警告信息。這些信息表明系統故意殺死進程或應用程序，而不是允許進程崩潰。</p><p>例如:</p><pre><code>[33238.178288] Out of memory: Kill process 6230 (firefox) score 53 or sacrifice child
[29923450.995084] select 5230 (docker), adj 0, size 708, to kill
</code></pre><p>你可以使用像 grep 這樣的工具找到這些日誌。這個例子是在 ubuntu 中:</p><pre><code>$ grep “Out of memory” /var/log/syslog
 [33238.178288] Out of memory: Kill process 6230 (firefox) score 53 or sacrifice child
</code></pre><p>請記住，grep 也要使用內存，所以只是運行 grep 也可能導致內存不足的錯誤。這是另一個你應該中央化存儲日誌的原因！</p><h3 id="定時任務錯誤日誌" tabindex="-1">定時任務錯誤日誌 <a class="header-anchor" href="#定時任務錯誤日誌" aria-label="Permalink to “定時任務錯誤日誌”">​</a></h3><p>cron 守護程序是一個調度器，可以在指定的日期和時間運行進程。如果進程運行失敗或無法完成，那麼 cron 的錯誤出現在你的日誌文件中。具體取決於你的發行版，你可以在 /var/log/cron，/var/log/messages，和 /var/log/syslog 幾個位置找到這個日誌。cron 任務失敗原因有很多。通常情況下，問題出在進程中而不是 cron 守護進程本身。</p><p>默認情況下，cron 任務的輸出會通過 postfix 發送電子郵件。這是一個顯示了該郵件已經發送的日誌。不幸的是，你不能在這裏看到郵件的內容。</p><pre><code>Mar 13 16:35:01 PSQ110 postfix/pickup[15158]: C3EDC5800B4: uid=1001 from=&lt;hoover&gt;
Mar 13 16:35:01 PSQ110 postfix/cleanup[15727]: C3EDC5800B4: message-id=&lt;20150310110501.C3EDC5800B4@PSQ110&gt;
Mar 13 16:35:01 PSQ110 postfix/qmgr[15159]: C3EDC5800B4: from=&lt;hoover@loggly.com&gt;, size=607, nrcpt=1 (queue active)
Mar 13 16:35:05 PSQ110 postfix/smtp[15729]: C3EDC5800B4: to=&lt;hoover@loggly.com&gt;, relay=gmail-smtp-in.l.google.com[74.125.130.26]:25, delay=4.1, delays=0.26/0/2.2/1.7, dsn=2.0.0, status=sent (250 2.0.0 OK 1425985505 f16si501651pdj.5 - gsmtp)
</code></pre><p>你可以考慮將 cron 的標準輸出記錄到日誌中，以幫助你定位問題。這是一個你怎樣使用 logger 命令重定向 cron 標準輸出到 syslog的例子。用你的腳本來代替 echo 命令，helloCron 可以設置為任何你想要的應用程序的名字。</p><pre><code>*/5 * * * * echo ‘Hello World’ 2&gt;&amp;1 | /usr/bin/logger -t helloCron
</code></pre><p>它創建的日誌條目：</p><pre><code>Apr 28 22:20:01 ip-172-31-11-231 CRON[15296]: (ubuntu) CMD (echo &#39;Hello World!&#39; 2&gt;&amp;1 | /usr/bin/logger -t helloCron)
Apr 28 22:20:01 ip-172-31-11-231 helloCron: Hello World!
</code></pre><p>每個 cron 任務將根據任務的具體類型以及如何輸出數據來記錄不同的日誌。</p><p>希望在日誌中有問題根源的線索，也可以根據需要添加額外的日誌記錄。</p><hr>`,38)),t("p",null,[e[4]||(e[4]=o("via: ",-1)),n(r,{href:"http://www.loggly.com/ultimate-guide/logging/troubleshooting-with-linux-logs/"},{default:s(()=>[...e[3]||(e[3]=[o("http://www.loggly.com/ultimate-guide/logging/troubleshooting-with-linux-logs/",-1)])]),_:1})]),t("p",null,[e[10]||(e[10]=o("作者：",-1)),n(r,{href:"https://www.linkedin.com/in/jasonskowronski"},{default:s(()=>[...e[5]||(e[5]=[o("Jason Skowronski",-1)])]),_:1}),e[11]||(e[11]=o(" 作者：",-1)),n(r,{href:"https://www.linkedin.com/in/amyecheverri"},{default:s(()=>[...e[6]||(e[6]=[o("Amy Echeverri",-1)])]),_:1}),e[12]||(e[12]=o(" 作者：",-1)),n(r,{href:"https://www.linkedin.com/pub/sadequl-hussain/14/711/1a7"},{default:s(()=>[...e[7]||(e[7]=[o("Sadequl Hussain",-1)])]),_:1}),e[13]||(e[13]=o(" 譯者：",-1)),n(r,{href:"https://github.com/strugglingyouth"},{default:s(()=>[...e[8]||(e[8]=[o("strugglingyouth",-1)])]),_:1}),e[14]||(e[14]=o(" 校對：",-1)),n(r,{href:"https://github.com/wxy"},{default:s(()=>[...e[9]||(e[9]=[o("wxy",-1)])]),_:1})]),t("p",null,[e[17]||(e[17]=o("本文由 ",-1)),n(r,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...e[15]||(e[15]=[o("LCTT",-1)])]),_:1}),e[18]||(e[18]=o(" 原創翻譯，",-1)),n(r,{href:"https://linux.cn/"},{default:s(()=>[...e[16]||(e[16]=[o("Linux中國",-1)])]),_:1}),e[19]||(e[19]=o(" 榮譽推出",-1))])])}const T=i(d,[["render",g]]);export{C as __pageData,T as default};
